// Scope.cs
/// <summary>
/// An <see cref="Scope"/> is a sequence of ASCII letters, digits, '/', '-', '_' or '*' that defines a resolved scope.
/// </summary>
[ComparableValue(ImplicitDowncast = false)]
public readonly partial struct Scope : IComparableValue<Scope, AsciiString>
{
    // The _value field, Parse, and equality members are generated by [ComparableValue].

    private const int MinLength = 1;
    private const int MaxLength = 255;

    public static bool IsValidValue(AsciiString value)
    {
        if (value.Length is < MinLength or > MaxLength)
        {
            return false;
        }

        if (value[0] != '/')
        {
            return false;
        }

        if (value.Length == 1)
        {
            return true;
        }

        if (value[^1] == '/')
        {
            return false;
        }

        for (var i = 0; i < value.Length; i++)
        {
            var c = value[i];

            if (AsciiChar.IsLetterOrDigit(c) || c == '_' || c == '/' || c == '-')
            {
                continue;
            }

            if (i == value.Length - 1 && c == '*')
            {
                continue;
            }

            return false;
        }

        return true;
    }

    public bool Matches(Scope scope)
    {
        var thisWildcardIndex = _value.IndexOf((AsciiChar)'*');
        var otherWildcardIndex = scope._value.IndexOf((AsciiChar)'*');

        if (thisWildcardIndex < 0 && otherWildcardIndex < 0)
        {
            return _value == scope._value;
        }

        if (thisWildcardIndex >= 0 && otherWildcardIndex >= 0)
        {
            return thisWildcardIndex == otherWildcardIndex
                && _value[..thisWildcardIndex] == scope._value[..otherWildcardIndex];
        }

        // Exactly one side has a wildcard here (the both-present and both-absent cases returned
        // above). Use '>= 0' so the side actually holding the wildcard is selected even when it
        // sits at index 0; '> 0' would misselect for a wildcard-at-start scope.
        var (wci, wildcardValue, otherValue) = thisWildcardIndex >= 0
            ? (thisWildcardIndex, _value, scope._value)
            : (otherWildcardIndex, scope._value, _value);

        var prefix = wildcardValue[..wci];

        if (!otherValue.StartsWith(prefix))
        {
            return false;
        }

        var suffix = otherValue[wci..];

        return suffix.IndexOf((AsciiChar)'/') < 0;
    }
}

// ScopeTests.cs
public sealed class ScopeTests
{
    [Theory]
    [MemberData(nameof(ValidValues))]
    public void IsValidValue_WithValidValues_ShouldReturnTrue(string value)
    {
        // Act
        var result = Scope.IsValidValue(AsciiString.Parse(value, CultureInfo.InvariantCulture));

        // Assert
        Assert.True(result);
    }

    [Theory]
    [MemberData(nameof(InvalidValues))]
    public void IsValidValue_WithInvalidValues_ShouldReturnFalse(string value)
    {
        // Act
        var result = Scope.IsValidValue(AsciiString.Parse(value, CultureInfo.InvariantCulture));

        // Assert
        Assert.False(result);
    }

    [Theory]
    [InlineData("/records/trackers/dse_trk_w4fv8do7fgbhyufdci/observers/*")]
    [InlineData("/records/trackers/dse_trk_w4fv8do7fgbhyufdci/observers")]
    public void Matches_WithSameValue_ShouldReturnTrue(string value)
    {
        // Arrange
        var scope = Scope.Parse(value, CultureInfo.InvariantCulture);

        // Act
        var result = scope.Matches(scope);

        // Assert
        Assert.True(result);
    }

    [Fact]
    public void Matches_WithWildcardMatching_ShouldReturnTrue()
    {
        // Arrange
        var scope = Scope.Parse("/records/trackers/dse_trk_w4fv8do7fgbhyufdci/observers/*", CultureInfo.InvariantCulture);
        var scope2 = Scope.Parse("/records/trackers/dse_trk_w4fv8do7fgbhyufdci/observers/123", CultureInfo.InvariantCulture);

        // Act
        var result = scope.Matches(scope2);
        var result2 = scope2.Matches(scope);

        // Assert
        Assert.True(result);
        Assert.True(result2);
    }

    [Fact]
    public void Matches_WithWildcardAcrossSegmentBoundary_ShouldReturnFalse()
    {
        // A trailing wildcard matches within a single path segment only — it must not match a
        // scope that descends into a further segment.
        var pattern = Scope.Parse("/records/trackers/*", CultureInfo.InvariantCulture);
        var deeper = Scope.Parse("/records/trackers/trk_1/observers", CultureInfo.InvariantCulture);

        Assert.False(pattern.Matches(deeper));
        Assert.False(deeper.Matches(pattern));
    }

    public static IEnumerable<TheoryDataRow<string>> ValidValues()
    {
        yield return "/";
        yield return "/records";
        yield return "/records/trackers/dse_trk_w4fv8do7fgbhyufdci";
        yield return "/records/trackers/dse_trk_w4fv8do7fgbhyufdci/observers/*";
    }

    public static IEnumerable<TheoryDataRow<string>> InvalidValues()
    {
        yield return "";
        yield return "records";
        yield return "/records/";
        yield return "/records/trackers/dse_trk_w4fv8do7fgbhyufdci/observers/*/";
        yield return "/records/trackers/*/observers";
        yield return "/records/trackers/*/observers/*";
    }
}
